package com.flippingfriend.companion;
/** Pure fail-closed binding to CandidateFactory's effective quantity-specific calibration choice. */
final class BuyReplacementQuantityDurationCalibrationInputContextComposer {
 BuyReplacementQuantityDurationCalibrationInputContext compose(BuyReplacementQuantityRoundTripCompletionEvaluationSet s,FillCalibration calibration,boolean learningDisabled,long at){if(s==null||at<s.getEvaluatedAt()||s.getEvaluatedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty()||s.getViableCandidates()==null||s.getViableCandidates().size()!=s.getEvaluations().size())return null;for(int i=0;i<s.getEvaluations().size();i++)if(!valid(s.getEvaluations().get(i),s.getViableCandidates().get(i),s))return null;FillCalibration effective=learningDisabled||calibration==null?FillCalibration.NEUTRAL:calibration;double multiplier=effective.waitMultiplier(s.getItemId());if(!Double.isFinite(multiplier)||multiplier<=0)return null;return new BuyReplacementQuantityDurationCalibrationInputContext(s,learningDisabled,multiplier,at);}
 private static boolean valid(BuyReplacementQuantityRoundTripCompletionEvaluation e,BuyReplacementQuantityFillViableCandidate v,BuyReplacementQuantityRoundTripCompletionEvaluationSet s){return e!=null&&v!=null&&e.getFillableQuantity()==s.getExactRemainderQuantity()&&e.getQuantity()>0&&e.getQuantity()<=e.getFillableQuantity()&&e.getBuyOffsetIndex()==v.getBuyOffsetIndex()&&e.getSellOffsetIndex()==v.getSellOffsetIndex()&&e.getBuyPrice()==v.getBuyPrice()&&e.getSellPrice()==v.getSellPrice()&&e.getSizeGridIndex()==v.getSizeGridIndex()&&Double.compare(e.getSizeShare(),v.getSizeShare())==0&&Double.compare(e.getKellyFraction(),v.getKellyFraction())==0&&Double.compare(e.getExpectedProfit(),v.getExpectedProfit())==0&&e.getWorstLoss()==v.getWorstLoss()&&Double.compare(e.getBuyProbability(),v.getBuyProbability())==0&&Double.compare(e.getSellProbability(),v.getSellProbability())==0&&Double.compare(e.getBuyExpectedHours(),v.getBuyExpectedHours())==0&&Double.compare(e.getBuyUnitsPerHour(),v.getBuyUnitsPerHour())==0&&Double.compare(e.getBuyWaitHours(),v.getBuyWaitHours())==0&&Double.compare(e.getSellExpectedHours(),v.getSellExpectedHours())==0&&Double.compare(e.getSellUnitsPerHour(),v.getSellUnitsPerHour())==0&&Double.compare(e.getSellWaitHours(),v.getSellWaitHours())==0&&Double.isFinite(e.getBuyProbability())&&e.getBuyProbability()>0&&e.getBuyProbability()<=1&&Double.isFinite(e.getSellProbability())&&e.getSellProbability()>0&&e.getSellProbability()<=1&&Double.isFinite(e.getBuyExpectedHours())&&e.getBuyExpectedHours()>=0&&Double.isFinite(e.getSellExpectedHours())&&e.getSellExpectedHours()>=0&&Double.isFinite(e.getBuyUnitsPerHour())&&e.getBuyUnitsPerHour()>=0&&Double.isFinite(e.getSellUnitsPerHour())&&e.getSellUnitsPerHour()>=0&&!Double.isNaN(e.getBuyWaitHours())&&e.getBuyWaitHours()>=0&&!Double.isNaN(e.getSellWaitHours())&&e.getSellWaitHours()>=0&&Double.compare(e.getCompletionProbability(),e.getBuyProbability()*e.getSellProbability())==0;}
}
